examples.query:
query {
  orders(first: 10) {
    edges {
      cursor
      node {
        id
      }
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
    }
  }
}

query {
  order1: order(id: "gid://shopify/Order/148977776") {
    name
  }
  order2: order(id: "gid://shopify/Order/1073459961") {
    name
  }
}

query {
  orders(first: 5) {
    edges {
      node {
        id
        name
        createdAt
        displayFinancialStatus
        displayFulfillmentStatus
        totalPriceSet {
          shopMoney {
            amount
            currencyCode
          }
        }
        subtotalPriceSet {
          shopMoney {
            amount
            currencyCode
          }
        }
        email
        shippingAddress {
          address1
          city
          provinceCode
          zip
        }
        lineItems(first: 5) {
          edges {
            node {
              name
              quantity
              sku
              variant {
                id
                title
              }
            }
          }
        }
      }
    }
  }
}

query {
  orders(first: 10, query: "updated_at:>2019-12-01") {
    edges {
      node {
        id
        updatedAt
      }
    }
  }
}

query {
  orders(first: 10, query: "financial_status:authorized") {
    edges {
      node {
        id
        displayFinancialStatus
      }
    }
  }
}

